fn parse_int(s: Str) -> Option[Int] {
  // simplified: only handles single digits
  if s.len() == 0 { return None; }
  return Some(0);
}

fn square_if_even(n: Int) -> Option[Int] {
  if n % 2 == 0 { return Some(n * n); }
  return None;
}

fn main() -> Int {
  let input = "6";
  // For this exercise, assume parsing returns Some(6)
  let result = Some(6).map(|x| x * x);
  return result.unwrap_or(0);
}
